export function chooseEvent(random,pair='USDJPY',excluded=[]){const eligible=EVENT_CATALOG.filter(e=>Math.abs(e.response[pair]??0)>.01),filtered=eligible.filter(e=>!excluded.includes(e.id)),pool=filtered.length?filtered:eligible,total=pool.reduce((s,e)=>s+e.weight,0);let r=random()*total;return pool.find(e=>(r-=e.weight)<0)??pool.at(-1);}
export class EventDirector{
 constructor(seed){this.rng=(seed^0x51ed270b)>>>0||1;this.cooldown=0;this.serial=0;this.lastId=null;this.recent=[];this.openTicks=0;}
 random(){let x=this.rng;x^=x<<13;x^=x>>>17;x^=x<<5;this.rng=x>>>0;return(this.rng+.5)/4294967296;}
 advance(time,instruments){this.openTicks=(this.openTicks??0)+1;this.recent??=[];this.cooldown=Math.max(0,this.cooldown-1);const stress=instruments.some(q=>q.market.state==='stress');if(this.openTicks<=45||this.cooldown||this.random()>(stress?.012:.0075))return null;let template=chooseEvent(()=>this.random(),'USDJPY',this.recent);if(template.id===this.lastId)template=EVENT_CATALOG[(EVENT_CATALOG.indexOf(template)+1)%EVENT_CATALOG.length];this.lastId=template.id;this.recent=[...this.recent,template.id].slice(-8);this.serial++;const spec={template,sign:this.random()<.5?-1:1,draws:Array.from({length:6},()=>this.random()),sharedId:this.serial};for(const q of instruments)q.market.createEvent(time,spec);this.cooldown=18+Math.floor(this.random()*18);return template.id;}
 static restore(data,seed){return Object.assign(new EventDirector(seed),data??{});}
}
